// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";
import {ClonesWithImmutableArgs} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;
    function setUp() public {
        c = new Cooler();
    }

    function testFuzz_property(address ownerAddr, address collatAddr) public {
        vm.assume(ownerAddr != collatAddr);
        vm.assume(ownerAddr != address(0));
        vm.assume(collatAddr != address(0));

        bytes memory data = abi.encodePacked(ownerAddr, collatAddr, address(this), address(this));
        address payable cloneAddr = ClonesWithImmutableArgs.clone(address(c), data);
        Cooler clone = Cooler(cloneAddr);

        assertTrue(clone.owner() == ownerAddr);
    }
}
